from pathlib import Path

root = Path(__file__).resolve().parents[2]

csproj_path = root / "tests/CSharpGit.Desktop.Tests/CSharpGit.Desktop.Tests.csproj"
csproj = csproj_path.read_text(encoding="utf-8")
layout_link = '    <Compile Include="../../src/CSharpGit.Presentation/Controls/CommitGraph/CommitGraphLayoutState.cs" Link="CommitGraph/CommitGraphLayoutState.cs" />\n'
if "CommitGraphLayoutState.cs" not in csproj:
    needle = '    <Compile Include="../../src/CSharpGit.Presentation/Controls/CommitGraph/CommitGraphMetrics.cs" Link="CommitGraph/CommitGraphMetrics.cs" />\n'
    if needle not in csproj:
        raise RuntimeError("CommitGraphMetrics link was not found in desktop test project")
    csproj = csproj.replace(needle, needle + layout_link, 1)
    csproj_path.write_text(csproj, encoding="utf-8", newline="\n")

adaptive_path = root / "tests/CSharpGit.Desktop.Tests/CommitGraphAdaptiveLayoutTests.cs"
adaptive_path.write_text('''using CSharpGit.Presentation.Controls.CommitGraph;\n\nnamespace CSharpGit.Desktop.Tests;\n\npublic sealed class CommitGraphAdaptiveLayoutTests\n{\n    [Theory]\n    [InlineData(1, 120, 16)]\n    [InlineData(7, 120, 16)]\n    [InlineData(8, 136, 16)]\n    [InlineData(9, 152, 16)]\n    [InlineData(12, 200, 16)]\n    public void LayoutUsesExpectedWidthBeforeCompression(int laneCount, double expectedWidth, double expectedLaneWidth)\n    {\n        var state = new CommitGraphLayoutState();\n\n        state.ObserveLaneCount(laneCount);\n\n        Assert.Equal(expectedWidth, state.GraphWidth, 6);\n        Assert.Equal(expectedLaneWidth, state.LaneWidth, 6);\n    }\n\n    [Fact]\n    public void ThirteenLanesKeepTwoHundredPixelColumnAndCompressSpacing()\n    {\n        var state = new CommitGraphLayoutState();\n\n        state.ObserveLaneCount(13);\n\n        Assert.Equal(200, state.GraphWidth, 6);\n        Assert.Equal(176d / 12d, state.LaneWidth, 6);\n        Assert.InRange(state.LaneWidth, CommitGraphMetrics.MinLaneWidth, CommitGraphMetrics.DefaultLaneWidth);\n    }\n\n    [Theory]\n    [InlineData(23)]\n    [InlineData(24)]\n    [InlineData(100)]\n    public void ExtremeTopologyNeverCompressesBelowMinimum(int laneCount)\n    {\n        var state = new CommitGraphLayoutState();\n\n        state.ObserveLaneCount(laneCount);\n\n        Assert.Equal(CommitGraphMetrics.MaxGraphWidth, state.GraphWidth);\n        Assert.Equal(CommitGraphMetrics.MinLaneWidth, state.LaneWidth);\n    }\n\n    [Fact]\n    public void LayoutIsMonotonicUntilSessionReset()\n    {\n        var state = new CommitGraphLayoutState();\n\n        state.ObserveLaneCount(5);\n        state.ObserveLaneCount(7);\n        state.ObserveLaneCount(9);\n        Assert.Equal(152, state.GraphWidth);\n        Assert.Equal(16, state.LaneWidth);\n\n        state.ObserveLaneCount(4);\n        Assert.Equal(9, state.ObservedMaxLaneCount);\n        Assert.Equal(152, state.GraphWidth);\n        Assert.Equal(16, state.LaneWidth);\n\n        state.ObserveLaneCount(13);\n        var compressedLaneWidth = state.LaneWidth;\n        state.ObserveLaneCount(16);\n        Assert.Equal(200, state.GraphWidth);\n        Assert.True(state.LaneWidth < compressedLaneWidth);\n\n        state.Reset();\n        Assert.Equal(0, state.ObservedMaxLaneCount);\n        Assert.Equal(120, state.GraphWidth);\n        Assert.Equal(16, state.LaneWidth);\n    }\n\n    [Fact]\n    public void SameEffectiveMetricsGiveSameLaneCoordinateAcrossRows()\n    {\n        var state = new CommitGraphLayoutState();\n        state.ObserveLaneCount(13);\n        var metrics = state.Metrics;\n        var first = new CommitGraphRowVisual(3, 3, 13, [new(3, 3, 3)], [new(3, 3, 3)]);\n        var second = new CommitGraphRowVisual(3, 7, 13, [new(3, 3, 7)], [new(3, 3, 7)]);\n\n        var firstGeometry = CommitGraphGeometryBuilder.Build(first, 24, metrics);\n        var secondGeometry = CommitGraphGeometryBuilder.Build(second, 24, metrics);\n\n        Assert.Equal(firstGeometry.Node?.Center.X, secondGeometry.Node?.Center.X);\n        Assert.Equal(metrics.GetLaneX(3), firstGeometry.Node?.Center.X);\n    }\n}\n''', encoding="utf-8", newline="\n")

contract_path = root / "tests/CSharpGit.Desktop.Tests/CommitGraphAdaptiveLayoutContractTests.cs"
contract_path.write_text('''namespace CSharpGit.Desktop.Tests;\n\npublic sealed class CommitGraphAdaptiveLayoutContractTests\n{\n    [Fact]\n    public void HeaderAndRowsDoNotOwnIndependentFixedGraphWidths()\n    {\n        var root = FindRepositoryRoot();\n        var mainPage = File.ReadAllText(Path.Combine(root, "src", "CSharpGit.Presentation", "MainPage.xaml"));\n        var workspace = File.ReadAllText(Path.Combine(root, "src", "CSharpGit.Presentation", "Styles", "Workspace.xaml"));\n\n        Assert.DoesNotContain("120,*,160,150,90", mainPage, StringComparison.Ordinal);\n        Assert.DoesNotContain("120,*,160,150,90", workspace, StringComparison.Ordinal);\n        Assert.Contains("HistoryGraphHeaderColumn", mainPage, StringComparison.Ordinal);\n        Assert.Contains("HistoryRowRoot", workspace, StringComparison.Ordinal);\n        Assert.Contains("HistoryList_ContainerContentChanging", mainPage, StringComparison.Ordinal);\n    }\n\n    [Fact]\n    public void ConverterConsumesPersistedLaneCountWithoutScanningEdges()\n    {\n        var root = FindRepositoryRoot();\n        var converter = File.ReadAllText(Path.Combine(root, "src", "CSharpGit.Presentation", "Controls", "CommitTopologyToGraphVisualConverter.cs"));\n\n        Assert.Contains("var laneCount = topology.LaneCount;", converter, StringComparison.Ordinal);\n        Assert.DoesNotContain("SelectMany", converter, StringComparison.Ordinal);\n        Assert.DoesNotContain("allEdges", converter, StringComparison.Ordinal);\n    }\n\n    [Fact]\n    public void GraphControlCachesEffectiveMetricsAndOwnsHardClip()\n    {\n        var root = FindRepositoryRoot();\n        var control = File.ReadAllText(Path.Combine(root, "src", "CSharpGit.Presentation", "Controls", "CommitGraph", "CommitGraphControl.cs"));\n\n        Assert.Contains("_renderedMetrics != Metrics", control, StringComparison.Ordinal);\n        Assert.Contains("Clip = _clipGeometry", control, StringComparison.Ordinal);\n        Assert.Contains("CommitGraphGeometryBuilder.Build(Graph, height, Metrics)", control, StringComparison.Ordinal);\n    }\n\n    private static string FindRepositoryRoot()\n    {\n        var directory = new DirectoryInfo(AppContext.BaseDirectory);\n        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "CSharpGit.slnx"))) directory = directory.Parent;\n        return directory?.FullName ?? throw new DirectoryNotFoundException("CSharpGit repository root was not found.");\n    }\n}\n''', encoding="utf-8", newline="\n")
